class NVWorkCalendarCopyRotating extends RunBaseBatch implements BatchRetryable
{
    CalendarId      calendarId;
    FromDate        fromDate;
    Days            incDays;

    DialogField     dlgCalendarId;
    DialogField     dlgFromDate;
    DialogField     dlgDays;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        calendarId,
        fromDate,
        incDays
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();

    dlgCalendarId   = dialog.addFieldValue(extendedTypeStr(CalendarId), calendarId);
    dlgCalendarId.value(calendarId);
    dlgCalendarId.enabled(false);

    dlgFromDate     = dialog.addFieldValue(extendedTypeStr(FromDate), fromDate);
    dlgDays         = dialog.addFieldValue(extendedTypeStr(Days), incDays);
    dlgDays.label("Days to copy");

    return dialog;
}

public boolean getFromDialog()
{
    fromDate    = dlgFromDate.value();
    incDays     = dlgDays.value();
    calendarId  = dlgCalendarId.value();

    return super();
}

public void run()
{
    #OCCRetryCount
    try
    {
        ttsbegin;
        int startIndex = incDays;
        int incIndex = 0;

        while(true)
        {
            WorkCalendarDate toCalendarDate;
            select firstonly toCalendarDate
                where toCalendarDate.CalendarId == calendarId
                    && toCalendarDate.TransDate == (fromDate + startIndex);

            if(toCalendarDate.RecId == 0)
                break;

            WorkCalendarDate calendarDate;
            select firstonly calendarDate
                where calendarDate.CalendarId   == calendarId
                    && calendarDate.TransDate   == (fromDate + incIndex);

            toCalendarDate.selectForUpdate(true);

            toCalendarDate.ClosedForPickup  = calendarDate.ClosedForPickup;
            toCalendarDate.WorkTimeControl  = calendarDate.WorkTimeControl;

            toCalendarDate.update();

            WorkCalendarDateLine fromCalendarDateLine;
            WorkCalendarDateLine toCalendarDateLine;

            delete_from toCalendarDateLine
                where toCalendarDateLine.CalendarId       == toCalendarDate.CalendarId
                    && toCalendarDateLine.TransDate       == toCalendarDate.TransDate;
            while select fromCalendarDateLine
                where fromCalendarDateLine.CalendarId       == calendarDate.CalendarId
                    && fromCalendarDateLine.TransDate       == calendarDate.TransDate
            {
                toCalendarDateLine.data(fromCalendarDateLine);

                toCalendarDateLine.TransDate = toCalendarDate.TransDate;

                toCalendarDateLine.insert();
            }

            startIndex++;
            incIndex = incIndex >= incDays? 1: incIndex + 1;
        }
        ttscommit;

        Info("Operation completed");
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public boolean validate(Object _calledFrom = null)
{
    if (false)
        return checkFailed("");

    return true;
}

static NVWorkCalendarCopyRotating construct()
{
    return new NVWorkCalendarCopyRotating();
}

static ClassDescription description()
{
    return "Copy rotating shift";
}

static void main(Args args)
{
    WorkCalendarTable workCalendarTable = args.record() as WorkCalendarTable;

    NVWorkCalendarCopyRotating copyRotating = NVWorkCalendarCopyRotating::construct();

    copyRotating.setCalendarId(workCalendarTable.CalendarId);
    if (copyRotating.prompt())
    {
        copyRotating.runOperation();
    }
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
